{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "Melperone, the closest structural analogue sharing the aryl-butanone tertiary-amine scaffold, had an absolute oral bioavailability of 67 ± 28% in healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Haloperidol, a close butyrophenone analogue with a basic amine side chain, showed a mean absolute oral bioavailability of 35% in patients, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Bromperidol, another close butyrophenone analogue, had an oral bioavailability of 30% in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Encainide, a methoxyaromatic basic amine with a piperidine group, had an absolute oral bioavailability of 32 ± 7% in normal subjects, supporting F ≥ 20% for the query's similar ionizable amine and methoxyaryl features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Raloxifene's very low 2% bioavailability is contradictory in direction, but its poor F is driven by extensive phenolic glucuronidation, a liability absent in the query's methoxy-substituted, phenol-free structure, so transferability is low.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The most transferable experimental analogues are basic-amine aryl ketones/butyrophenones with absolute oral bioavailability values of 30–70%, all above the 20% threshold. Low-bioavailability analogues owe their poor F to specific metabolic liabilities such as phenolic glucuronidation or lactam hydrolysis that are not present in the query. Therefore, high oral bioavailability (F ≥ 20%) is better supported.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the exact 2,4,6-trimethoxyphenyl pyrrolidinylbutanone structure.",
    "Morgan similarities to the closest analogues are modest (<0.36), limiting quantitative transferability.",
    "The query's very low logD and full ionization at pH 7.4 raise uncertainty about passive permeability, though related ionizable basic amines still achieve F ≥ 20%.",
    "First-pass metabolism of the trimethoxyaryl motif is not directly characterized in the available evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

